// Validation against real, public-domain US EPA coast-down data (SAE J2263).
//
// Dataset: data/validation/epa_coastdown.json — 3,000+ MY2015/2016 vehicles, generated by
// tools/physics/import_epa_coastdown.mjs from the EPA Test Car List (US Government work, public domain).
//
// Part 1 checks every row's imperial→SI conversion and the road-load form. Part 2 drives the real
// WASM physics core through a neutral coast-down for a spread of real vehicles and compares the
// measured aerodynamic slope with the EPA C coefficient.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { loadPhysics } from '../index.js';
import { FlatGroundCar } from '../harness.js';

const data = JSON.parse(fs.readFileSync(new URL('../../../data/validation/epa_coastdown.json', import.meta.url), 'utf8'));
const LBF = 4.4482216, MPH = 0.44704, RHO = 1.225;

test('EPA dataset: provenance, size and coefficient sanity', () => {
  assert.match(data.source.license, /public domain/i);
  assert.match(data.schema, /epa-coastdown/);
  assert.ok(Array.isArray(data.vehicles) && data.vehicles.length > 1000, `vehicles ${data.vehicles.length}`);
  for (const v of data.vehicles) {
    assert.ok(v.a_lbf > 0 && v.b_lbf_per_mph >= 0 && v.c_lbf_per_mph2 > 0, `${v.make} ${v.model} coef`);
    assert.ok(v.mass_kg > 600 && v.mass_kg < 4500, `${v.make} ${v.model} mass ${v.mass_kg}`);
  }
  assert.ok(data.vehicles.some((v) => /corvette/i.test(v.model)), 'Corvette present');
  assert.ok(data.vehicles.some((v) => /golf/i.test(v.model)), 'Golf present');
});

test('EPA dataset: SI conversion is exact for every row', () => {
  for (const v of data.vehicles) {
    assert.ok(Math.abs(v.f0_n - v.a_lbf * LBF) < 0.02, `F0 ${v.testId}`);
    assert.ok(Math.abs(v.f1_n_s_per_m - (v.b_lbf_per_mph * LBF) / MPH) < 0.05, `F1 ${v.testId}`);
    assert.ok(Math.abs(v.f2_n_s2_per_m2 - (v.c_lbf_per_mph2 * LBF) / (MPH * MPH)) < 0.01, `F2 ${v.testId}`);
  }
});

test('EPA dataset: road-load power rises with speed for every vehicle', () => {
  const P = (v, mph) => (v.a_lbf + v.b_lbf_per_mph * mph + v.c_lbf_per_mph2 * mph * mph) * LBF * mph * MPH;
  for (const v of data.vehicles) {
    const p30 = P(v, 30), p50 = P(v, 50), p70 = P(v, 70), p90 = P(v, 90);
    assert.ok(p30 < p50 && p50 < p70 && p70 < p90, `${v.make} ${v.model} P monotonic`);
    assert.ok(p50 > 3000 && p50 < 80000, `${v.make} ${v.model} P50 ${p50}`);
  }
});

// ---- Part 2: drive the core through real coast-downs ------------------------------------------------
const physics = await loadPhysics();
const example = fs.readFileSync(new URL('../cars/example_coupe.json', import.meta.url), 'utf8');
const base = JSON.parse(example);

function specFor(v) {
  const s = structuredClone(base);
  s.chassis.mass_kg = v.mass_kg;
  // EPA C is the quadratic road-load term: F2 = 0.5 * rho * CdA  =>  CdA = 2*F2/rho
  s.aero.drag_area_m2 = (2 * v.f2_n_s2_per_m2) / RHO;
  s.aero.downforce_area_m2 = 0;
  return JSON.stringify(s);
}

function coastFit(v) {
  const car = physics.createCar(specFor(v));
  const sim = new FlatGroundCar(car);
  sim.setSpeed(30, 1);   // 108 km/h, neutral
  const dt = 1 / 240;
  const samples = [];
  for (let i = 0; i < 240 * 40; i++) {
    sim.step({ throttle: 0, brake: 0, steer: 0, handbrake: 0, gear: 1 }, dt);
    const speed = Math.hypot(...sim.vel);
    if (i % 24 === 0 && speed > 8 && speed < 26) samples.push({ t: sim.time, v: speed });
    if (speed < 8) break;
  }
  // central-difference deceleration, then least squares F = a + b*v^2
  const mEff = v.mass_kg * 1.04;
  const pts = [];
  const h = 5;
  for (let i = h; i + h < samples.length; i++) {
    const dv = (samples[i + h].v - samples[i - h].v) / (samples[i + h].t - samples[i - h].t);
    const vv = samples[i].v;
    pts.push({ x: vv * vv, y: -mEff * dv });
  }
  const n = pts.length;
  const sx = pts.reduce((a, p) => a + p.x, 0), sy = pts.reduce((a, p) => a + p.y, 0);
  const sxx = pts.reduce((a, p) => a + p.x * p.x, 0), sxy = pts.reduce((a, p) => a + p.x * p.y, 0);
  const slope = (n * sxy - sx * sy) / (n * sxx - sx * sx);
  return { measured: slope, expected: v.f2_n_s2_per_m2, n };
}

test('EPA coast-down: the core aero slope matches real vehicles', () => {
  const picks = [];
  const byMass = [...data.vehicles].sort((a, b) => a.mass_kg - b.mass_kg);
  for (let i = 0; i < 8; i++) picks.push(byMass[Math.floor(((i + 0.5) / 8) * byMass.length)]);
  const rows = [];
  for (const v of picks) {
    const r = coastFit(v);
    const err = Math.abs(r.measured - r.expected) / r.expected;
    rows.push(`${v.make} ${v.model}: measured ${r.measured.toFixed(3)} vs EPA ${r.expected.toFixed(3)} N/(m/s)^2 (${(err * 100).toFixed(1)}%)`);
    assert.ok(r.n > 50, `too few samples for ${v.model}`);
    assert.ok(err < 0.25, `aero slope off by ${(err * 100).toFixed(1)}% for ${v.make} ${v.model}\n${rows.join('\n')}`);
  }
  console.log(rows.join('\n'));
});
